package com.example.starter.bag.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

/**
 * 单条消息写入请求。负载以 Base64 传输，负载校验值由服务端计算。
 *
 * @param topic       Topic 名称
 * @param timestampNs 纳秒时间戳（UTC 纪元纳秒）
 * @param seq         Topic 内序列号，必须大于该 Topic 已提交的最大序列号
 * @param typeId      消息类型标识
 * @param payloadBase64 Base64 编码的消息负载，可为空
 * @param batchNo     写入批次号，同批次同参重试幂等
 */
public record WriteMessageRequest(
        @NotBlank String topic,
        @NotNull Long timestampNs,
        @PositiveOrZero long seq,
        @NotBlank String typeId,
        String payloadBase64,
        @NotBlank String batchNo) {
}

package com.example.starter.bag.web.dto;

/**
 * 写入结果。
 *
 * @param messageId 消息主键；幂等命中时返回既有消息 id
 * @param segmentId 所属分段 id
 * @param segIndex  Topic 内分段序号
 * @param duplicate 是否为同批次同参的幂等重试（true 表示未重复写入）
 */
public record WriteResult(long messageId, long segmentId, int segIndex, boolean duplicate) {
}

package com.example.starter.bag.web.dto;

/**
 * 查询返回的消息视图（负载以 Base64 返回）。
 */
public record MessageView(
        long id,
        String topic,
        long timestampNs,
        long seq,
        String typeId,
        String payloadBase64,
        String payloadChecksum,
        String batchNo,
        long segmentId) {
}

package com.example.starter.bag.web.dto;

import com.example.starter.bag.model.SegmentStatus;

/**
 * 逻辑分段视图。纳秒与序列号边界在空段时为 null。
 */
public record SegmentView(
        long id,
        String topic,
        int segIndex,
        Long startNs,
        Long endNs,
        Long startSeq,
        Long endSeq,
        long messageCount,
        int maxSize,
        SegmentStatus status,
        String checksum) {
}

package com.example.starter.bag.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 模拟写入中断 / 索引损坏的请求，仅用于恢复能力的业务测试入口。
 *
 * @param topic   Topic 名称
 * @param segIndex 目标分段序号
 * @param mode    故障模式：DROP_INDEX 删除段内索引 / INCOMPLETE_TAIL 追加无索引的不完整尾消息 / MARK_DAMAGED 仅标记损坏
 * @param tailSize INCOMPLETE_TAIL 模式下追加的不完整消息条数
 */
public record CorruptSegmentRequest(
        @NotBlank String topic,
        int segIndex,
        @NotNull FaultMode mode,
        @Positive Integer tailSize) {

    /** 故障模拟模式。 */
    public enum FaultMode {
        /** 删除该段全部索引行，模拟索引损坏 */
        DROP_INDEX,
        /** 直接写入若干不带索引、不更新链校验的尾消息，模拟写入中断 */
        INCOMPLETE_TAIL,
        /** 仅把段标记为 DAMAGED，不破坏数据 */
        MARK_DAMAGED
    }
}

package com.example.starter.bag.web.dto;

import java.util.List;

/**
 * 一次恢复操作的整体结果。
 *
 * @param segments 各受损分段的恢复明细
 */
public record RecoveryResult(List<SegmentRecoveryReport> segments) {
}

package com.example.starter.bag.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 回放请求。范围边界均可空，空表示不限制；playKey 相同的重复请求不重复创建回放记录。
 */
public record PlayRequest(
        @NotBlank String playKey,
        @NotBlank String topic,
        Long startNs,
        Long endNs,
        Long startSeq,
        Long endSeq) {
}

package com.example.starter.bag.web.dto;

import java.util.List;

/**
 * 回放结果。duplicated 为 true 时表示复用了既有回放记录，消息仍按原顺序返回。
 */
public record PlayResult(
        long playId,
        String playKey,
        String topic,
        long messageCount,
        String replayChecksum,
        boolean duplicated,
        List<MessageView> messages) {
}

