package com.example.starter.bag.repository;

import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Repository;

import org.springframework.transaction.annotation.Transactional;

import java.util.List;

/**
 * 二级索引数据访问。索引可独立删除与重建，是恢复操作的核心对象。
 */
@Repository
public class MessageIndexRepository {

    private final NamedParameterJdbcTemplate jdbc;

    public MessageIndexRepository(NamedParameterJdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** 为一条消息写入索引行。 */
    public void insert(long messageId, String topic, long timestampNs, long seq, long segmentId) {
        jdbc.update("""
                        INSERT INTO bag_msg_index (message_id, topic, timestamp_ns, seq, segment_id)
                        VALUES (:messageId, :topic, :timestampNs, :seq, :segmentId)
                        """,
                new MapSqlParameterSource()
                        .addValue("messageId", messageId)
                        .addValue("topic", topic)
                        .addValue("timestampNs", timestampNs)
                        .addValue("seq", seq)
                        .addValue("segmentId", segmentId));
    }

    /** 故障模拟：删除整段索引行。 */
    public int deleteBySegmentId(long segmentId) {
        return jdbc.update("DELETE FROM bag_msg_index WHERE segment_id = :segmentId",
                new MapSqlParameterSource("segmentId", segmentId));
    }

    /** 恢复：删除段内全部索引行后基于保留的完整前缀重建。 */
    @Transactional
    public int rebuildForSegment(long segmentId) {
        jdbc.update("DELETE FROM bag_msg_index WHERE segment_id = :segmentId",
                new MapSqlParameterSource("segmentId", segmentId));
        return jdbc.update("""
                        INSERT INTO bag_msg_index (message_id, topic, timestamp_ns, seq, segment_id)
                        SELECT id, topic, timestamp_ns, seq, segment_id
                        FROM bag_message
                        WHERE segment_id = :segmentId AND status = 'COMMITTED'
                        ORDER BY seq
                        """,
                new MapSqlParameterSource("segmentId", segmentId));
    }

    /** 统计段内索引行数（恢复校验用）。 */
    public long countBySegmentId(long segmentId) {
        return jdbc.queryForObject("SELECT COUNT(*) FROM bag_msg_index WHERE segment_id = :segmentId",
                new MapSqlParameterSource("segmentId", segmentId), Long.class);
    }

    /** 列出段内缺失索引的已提交消息 id（恢复完整性自检用）。 */
    public List<Long> findCommittedIdsWithoutIndex(long segmentId) {
        return jdbc.queryForList("""
                        SELECT m.id FROM bag_message m
                        LEFT JOIN bag_msg_index i ON i.message_id = m.id
                        WHERE m.segment_id = :segmentId AND m.status = 'COMMITTED' AND i.id IS NULL
                        ORDER BY m.seq
                        """,
                new MapSqlParameterSource("segmentId", segmentId), Long.class);
    }
}

package com.example.starter.bag.repository;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.List;

/**
 * 回放记录数据访问。play_key 唯一约束保证重复请求不重复创建记录。
 */
@Repository
public class PlayRepository {

    /** 回放记录行。 */
    public record PlayRow(
            long id,
            String playKey,
            String topic,
            Long startNs,
            Long endNs,
            Long startSeq,
            Long endSeq,
            long messageCount,
            String replayChecksum) {
    }

    private static final RowMapper<PlayRow> MAPPER = (rs, n) -> new PlayRow(
            rs.getLong("id"),
            rs.getString("play_key"),
            rs.getString("topic"),
            rs.getObject("start_ns", Long.class),
            rs.getObject("end_ns", Long.class),
            rs.getObject("start_seq", Long.class),
            rs.getObject("end_seq", Long.class),
            rs.getLong("message_count"),
            rs.getString("replay_checksum"));

    private final NamedParameterJdbcTemplate jdbc;

    public PlayRepository(NamedParameterJdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 尝试创建回放记录；play_key 冲突时返回 false，由调用方回查既有记录。
     */
    public boolean tryInsert(PlayRow row) {
        try {
            jdbc.update("""
                            INSERT INTO bag_play
                                (play_key, topic, start_ns, end_ns, start_seq, end_seq,
                                 message_count, replay_checksum)
                            VALUES (:playKey, :topic, :startNs, :endNs, :startSeq, :endSeq,
                                    :messageCount, :replayChecksum)
                            """,
                    new MapSqlParameterSource()
                            .addValue("playKey", row.playKey())
                            .addValue("topic", row.topic())
                            .addValue("startNs", row.startNs())
                            .addValue("endNs", row.endNs())
                            .addValue("startSeq", row.startSeq())
                            .addValue("endSeq", row.endSeq())
                            .addValue("messageCount", row.messageCount())
                            .addValue("replayChecksum", row.replayChecksum()));
            return true;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }

    /** 按幂等键查询既有回放记录，不存在返回 null。 */
    public PlayRow findByKey(String playKey) {
        List<PlayRow> rows = jdbc.query("SELECT * FROM bag_play WHERE play_key = :playKey",
                new MapSqlParameterSource("playKey", playKey), MAPPER);
        return rows.isEmpty() ? null : rows.get(0);
    }
}

