void concurrentWritesToSameTopicNeverDuplicateOrReorderSeq() throws Exception {
    String topic = uniqueTopic();
    int threads = 8;
    int perThread = 10;
    ExecutorService pool = Executors.newFixedThreadPool(threads);
    CountDownLatch start = new CountDownLatch(1);
    List<Future<?>> futures = new ArrayList<>();
    AtomicInteger success = new AtomicInteger();

    try {
        for (int t = 0; t < threads; t++) {
            final int base = t * perThread;
            futures.add(pool.submit(() -> {
                start.await();
                for (int i = 0; i < perThread; i++) {
                    long seq = base + i;
                    WriteResult r = write(topic, seq, 1000L + seq, "p" + seq, "batch-" + seq);
                    assertFalse(r.duplicate());
                    success.incrementAndGet();
                }
                return null;
            }));
        }
        start.countDown();
        for (Future<?> f : futures) {
            assertDoesNotThrow(() -> f.get(30, TimeUnit.SECONDS));
        }
    } finally {
        pool.shutdown();
        assertTrue(pool.awaitTermination(30, TimeUnit.SECONDS));
    }

    assertEquals(threads * perThread, success.get());
    List<Long> seqs = service.query(topic, null, null, null, null)
            .stream().map(MessageView::seq).sorted().toList();
    assertEquals(threads * perThread, seqs.size());
    for (long seq = 0; seq < threads * perThread; seq++) {
        assertEquals(seq, seqs.get((int) seq));
    }
}

