1	package com.example.starter.bag.service;
2	
3	import com.example.starter.bag.config.BagProperties;
4	import com.example.starter.bag.model.SegmentStatus;
5	import com.example.starter.bag.repository.MessageIndexRepository;
6	import com.example.starter.bag.repository.MessageRepository;
7	import com.example.starter.bag.repository.MessageRepository.MessageRow;
8	import com.example.starter.bag.repository.PlayRepository;
9	import com.example.starter.bag.repository.PlayRepository.PlayRow;
10	import com.example.starter.bag.repository.SegmentRepository;
11	import com.example.starter.bag.repository.SegmentRepository.SegmentRow;
12	import com.example.starter.bag.web.BagExceptionHandler.ConflictException;
13	import com.example.starter.bag.web.dto.CorruptSegmentRequest;
14	import com.example.starter.bag.web.dto.CorruptSegmentRequest.FaultMode;
15	import com.example.starter.bag.web.dto.MessageView;
16	import com.example.starter.bag.web.dto.PlayRequest;
17	import com.example.starter.bag.web.dto.PlayResult;
18	import com.example.starter.bag.web.dto.RecoveryResult;
19	import com.example.starter.bag.web.dto.SegmentRecoveryReport;
20	import com.example.starter.bag.web.dto.SegmentView;
21	import com.example.starter.bag.web.dto.WriteMessageRequest;
22	import com.example.starter.bag.web.dto.WriteResult;
23	import org.springframework.dao.DuplicateKeyException;
24	import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
25	import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
26	import org.springframework.stereotype.Service;
27	import org.springframework.transaction.annotation.Transactional;
28	
29	import java.util.ArrayList;
30	import java.util.Base64;
31	import java.util.List;
32	import java.util.NoSuchElementException;
33	import java.util.Objects;
34	
35	/**
36	 * rosbag 风格消息存储核心服务。
37	 *
38	 * <p>写入：Topic 级串行（bag_topic_lock 行锁），同批次同参重试幂等，序列号单调不倒退，
39	 * 消息按 {@code bag.segment.max-size} 逻辑分段追加，消息与二级索引及段边界在同一事务落库。
40	 *
41	 * <p>查询：先用分段边界（粗索引）裁剪命中分段，再经 bag_msg_index 二级索引过滤时间/序列范围，
42	 * 不会把全部消息读入内存。
43	 *
44	 * <p>恢复：在单个事务内按段级链式校验定位可验证完整前缀，隔离未链入的中断尾消息，重建索引并重写边界。
45	 */
46	@Service
47	public class RosbagStorageService {
48	
49	    private final BagProperties properties;
50	    private final SegmentRepository segments;
51	    private final MessageRepository messages;
52	    private final MessageIndexRepository indexRepository;
53	    private final PlayRepository plays;
54	    private final NamedParameterJdbcTemplate jdbc;
55	
56	    public RosbagStorageService(BagProperties properties,
57	                                SegmentRepository segments,
58	                                MessageRepository messages,
59	                                MessageIndexRepository indexRepository,
60	                                PlayRepository plays,
61	                                NamedParameterJdbcTemplate jdbc) {
62	        this.properties = properties;
63	        this.segments = segments;
64	        this.messages = messages;
65	        this.indexRepository = indexRepository;
66	        this.plays = plays;
67	        this.jdbc = jdbc;
68	    }
69	
70	    /**
71	     * 追加单条消息。
72	     *
73	     * @throws ConflictException 序列号倒退、同批次参数不一致或段处于待恢复状态等业务冲突
74	     */
75	    @Transactional
76	    public WriteResult write(WriteMessageRequest request) {
77	        byte[] payload = decodePayload(request.payloadBase64());
78	        String payloadChecksum = Checksums.sha256(payload);
79	
80	        lockTopic(request.topic());
81	
82	        // 同批次同参重试：命中既有消息直接返回，不重复写入；即使段待恢复也允许幂等读取
83	        MessageRow existing = messages.findByBatchKey(request.batchNo(), request.topic(), request.seq());
84	        if (existing != null) {
85	            verifySameParams(existing, request, payloadChecksum);
86	            SegmentRow seg = segments.findById(existing.segmentId());
87	            return new WriteResult(existing.id(), existing.segmentId(), seg.segIndex(), true);
88	        }
89	
90	        if (segments.existsDamaged(request.topic())) {
91	            throw new ConflictException("Topic 存在待恢复的受损分段，必须先调用恢复接口再写入：topic="
92	                    + request.topic());
93	        }
94	
95	        Long maxSeq = messages.findMaxCommittedSeq(request.topic());
96	        if (maxSeq != null && request.seq() <= maxSeq) {
97	            throw new ConflictException("Topic 内序列号不得倒退：topic=" + request.topic()
98	                    + "，请求 seq=" + request.seq() + "，当前最大 seq=" + maxSeq);
99	        }
100	
101	        SegmentRow target = segments.findLatestForUpdate(request.topic());
102	        if (target == null || target.status() != SegmentStatus.OPEN
103	                || target.messageCount() >= target.maxSize()) {
104	            int nextIndex = segments.nextSegIndex(request.topic());
105	            long newId = segments.insert(request.topic(), nextIndex, properties.maxSize());
106	            target = segments.findByIdForUpdate(newId);
107	        }
108	
109	        String previous = target.checksum() == null ? "" : target.checksum();
110	        String chain = Checksums.chain(previous, request.topic(), request.seq(),
111	                request.timestampNs(), request.typeId(), payloadChecksum);
112	
113	        messages.insertCommitted(request.topic(), request.timestampNs(), request.seq(),
114	                request.typeId(), payload, payloadChecksum, chain, request.batchNo(), target.id());
115	        long messageId = requireId(messages.findByBatchKey(
116	                request.batchNo(), request.topic(), request.seq()));
117	        indexRepository.insert(messageId, request.topic(), request.timestampNs(),
118	                request.seq(), target.id());
119	
120	        long newCount = target.messageCount() + 1;
121	        if (newCount == 1) {
122	            segments.initBoundaries(target.id(), request.timestampNs(), request.seq(), chain);
123	        } else {
124	            segments.extendBoundaries(target.id(), request.timestampNs(), request.seq(), newCount, chain);
125	        }
126	        if (newCount >= target.maxSize()) {
127	            segments.updateStatus(target.id(), SegmentStatus.SEALED);
128	        }
129	        return new WriteResult(messageId, target.id(), target.segIndex(), false);
130	    }
131	
132	    /**
133	     * 组合范围查询。先定位相交分段，再走二级索引，结果按序列号原序返回；
134	     * DAMAGED 段不参与查询，必须先恢复。
135	     */
136	    @Transactional(readOnly = true)
137	    public List<MessageView> query(String topic, Long startNs, Long endNs, Long startSeq, Long endSeq) {
138	        validateRange(startNs, endNs, startSeq, endSeq);
139	        List<Long> candidateIds = segments.findCandidateSegmentIds(topic, startNs, endNs, startSeq, endSeq);
140	        if (candidateIds.isEmpty()) {
141	            return List.of();
142	        }
143	        return messages.queryViaIndex(candidateIds, topic, startNs, endNs, startSeq, endSeq)
144	                .stream().map(RosbagStorageService::toView).toList();
145	    }
146	
147	    /** 查看 Topic 下分段及边界、消息数、状态与段级校验。 */
148	    @Transactional(readOnly = true)
149	    public List<SegmentView> segments(String topic) {
150	        return segments.findByTopic(topic).stream()
151	                .map(s -> new SegmentView(s.id(), s.topic(), s.segIndex(), s.startNs(), s.endNs(),
152	                        s.startSeq(), s.endSeq(), s.messageCount(), s.maxSize(), s.status(), s.checksum()))
153	                .toList();
154	    }
155	
156	    /**
157	     * 测试入口：模拟写入中断或索引损坏。
158	     *
159	     * @throws NoSuchElementException 分段不存在
160	     * @throws ConflictException      目标段不是 Topic 最新段（不允许向历史段注入尾消息）
161	     */
162	    @Transactional
163	    public void corrupt(CorruptSegmentRequest request) {
164	        SegmentRow target = segments.findByTopicAndIndex(request.topic(), request.segIndex());
165	        if (target == null) {
166	            throw new NoSuchElementException("分段不存在：topic=" + request.topic()
167	                    + "，segIndex=" + request.segIndex());
168	        }
169	        SegmentRow latest = segments.findLatestForUpdate(request.topic());
170	        if (latest == null || latest.id() != target.id()) {
171	            throw new ConflictException("仅允许对 Topic 最新分段注入故障：topic=" + request.topic()
172	                    + "，segIndex=" + request.segIndex());
173	        }
174	
175	        switch (request.mode()) {
176	            case DROP_INDEX -> {
177	                indexRepository.deleteBySegmentId(target.id());
178	                segments.updateStatus(target.id(), SegmentStatus.DAMAGED);
179	            }
180	            case MARK_DAMAGED -> segments.updateStatus(target.id(), SegmentStatus.DAMAGED);
181	            case INCOMPLETE_TAIL -> {
182	                int tailSize = request.tailSize() == null ? 1 : request.tailSize();
183	                long baseSeq = target.endSeq() == null ? -1 : target.endSeq();
184	                long baseNs = target.endNs() == null ? 0L : target.endNs();
185	                for (int i = 1; i <= tailSize; i++) {
186	                    long seq = baseSeq + i;
187	                    long ts = baseNs + i;
188	                    byte[] payload = ("corrupt-tail-" + seq).getBytes(java.nio.charset.StandardCharsets.UTF_8);
189	                    messages.insertIncompleteTail(request.topic(), ts, seq, "corrupt/IncompleteTail",
190	                            payload, Checksums.sha256(payload),
191	                            "corrupt:" + target.id() + ":" + seq, target.id());
192	                    // 故意不写索引、不推进边界、不更新段级链校验，模拟写入中断
193	                }
194	                segments.updateStatus(target.id(), SegmentStatus.DAMAGED);
195	            }
196	        }
197	    }
198	
199	    /**
200	     * 恢复全部 DAMAGED 分段。对每个段：
201	     * 锁定段与消息 → 用段级链式校验找出可验证完整前缀 → 同事务隔离其余尾消息 →
202	     * 删除并重建二级索引 → 按前缀重写段边界与状态。
203	     */
204	    @Transactional
205	    public RecoveryResult recover() {
206	        List<SegmentRow> damaged = segments.findDamagedForUpdate();
207	        List<SegmentRecoveryReport> reports = new ArrayList<>();
208	        for (SegmentRow seg : damaged) {
209	            SegmentRow locked = segments.findByIdForUpdate(seg.id());
210	            List<MessageRow> all = messages.findAllBySegmentForUpdate(locked.id());
211	
212	            // 逐条验证完整前缀：负载校验值一致 + 链锚点可重算复现；
213	            // 遇到无锚点的中断尾消息或任何一处不匹配即停止，其后全部视为不完整消息。
214	            String running = "";
215	            int kept = 0;
216	            for (MessageRow row : all) {
217	                if (row.chainValue() == null) {
218	                    break;
219	                }
220	                if (!Objects.equals(Checksums.sha256(row.payload()), row.payloadChecksum())) {
221	                    break;
222	                }
223	                running = Checksums.chain(running, row.topic(), row.seq(), row.timestampNs(),
224	                        row.typeId(), row.payloadChecksum());
225	                if (!Objects.equals(running, row.chainValue())) {
226	                    break;
227	                }
228	                kept++;
229	            }
230	            boolean prefixVerified = kept > 0;
231	
232	            List<Long> tailIds = all.subList(kept, all.size()).stream().map(MessageRow::id).toList();
233	            long quarantined = messages.quarantineByIds(tailIds);
234	            long rebuilt = indexRepository.rebuildForSegment(locked.id());
235	
236	            Long startNs = null;
237	            Long endNs = null;
238	            Long startSeq = null;
239	            Long endSeq = null;
240	            String finalChecksum = null;
241	            if (kept > 0) {
242	                // 序列号按序追加，首/尾即最小/最大；纳秒时间戳不要求随序列号单调，按前缀聚合 min/max
243	                long minNs = Long.MAX_VALUE;
244	                long maxNs = Long.MIN_VALUE;
245	                for (int i = 0; i < kept; i++) {
246	                    MessageRow row = all.get(i);
247	                    minNs = Math.min(minNs, row.timestampNs());
248	                    maxNs = Math.max(maxNs, row.timestampNs());
249	                }
250	                MessageRow first = all.get(0);
251	                MessageRow last = all.get(kept - 1);
252	                startNs = minNs;
253	                endNs = maxNs;
254	                startSeq = first.seq();
255	                endSeq = last.seq();
256	                finalChecksum = last.chainValue();
257	            }
258	            // 末段且未写满才重新开放追加；非末段或已满一律封段
259	            boolean isLastSegment = locked.segIndex() == segments.maxSegIndex(locked.topic());
260	            SegmentStatus finalStatus =
261	                    (kept >= locked.maxSize() || !isLastSegment) ? SegmentStatus.SEALED : SegmentStatus.OPEN;
262	            segments.rewriteAfterRecovery(locked.id(), startNs, endNs, startSeq, endSeq,
263	                    kept, finalChecksum, finalStatus);
264	
265	            reports.add(new SegmentRecoveryReport(locked.topic(), locked.segIndex(), kept,
266	                    quarantined, rebuilt, prefixVerified, finalStatus.name()));
267	        }
268	        return new RecoveryResult(reports);
269	    }
270	
271	    /**
272	     * 按原顺序回放命中消息。相同 playKey 的并发或重复请求只创建一条 bag_play 记录，
273	     * 每次调用都返回当前命中的消息序列及其链校验值。
274	     */
275	    @Transactional
276	    public PlayResult play(PlayRequest request) {
277	        validateRange(request.startNs(), request.endNs(), request.startSeq(), request.endSeq());
278	        List<Long> candidateIds = segments.findCandidateSegmentIds(
279	                request.topic(), request.startNs(), request.endNs(), request.startSeq(), request.endSeq());
280	        List<MessageRow> rows = candidateIds.isEmpty()
281	                ? List.of()
282	                : messages.queryViaIndex(candidateIds, request.topic(),
283	                        request.startNs(), request.endNs(), request.startSeq(), request.endSeq());
284	
285	        String replayChecksum = "";
286	        for (MessageRow row : rows) {
287	            replayChecksum = Checksums.chain(replayChecksum, row.topic(), row.seq(),
288	                    row.timestampNs(), row.typeId(), row.payloadChecksum());
289	        }
290	        List<MessageView> views = rows.stream().map(RosbagStorageService::toView).toList();
291	
292	        PlayRow candidate = new PlayRow(0, request.playKey(), request.topic(),
293	                request.startNs(), request.endNs(), request.startSeq(), request.endSeq(),
294	                rows.size(), replayChecksum);
295	        boolean created = plays.tryInsert(candidate);
296	        PlayRow saved = requirePlay(plays.findByKey(request.playKey()));
297	
298	        return new PlayResult(saved.id(), saved.playKey(), saved.topic(), saved.messageCount(),
299	                saved.replayChecksum(), !created, views);
300	    }
301	
302	    // ---- 内部辅助 ------------------------------------------------------
303	
304	    private void lockTopic(String topic) {
305	        try {
306	            jdbc.update("INSERT INTO bag_topic_lock (topic) VALUES (:topic)",
307	                    new MapSqlParameterSource("topic", topic));
308	        } catch (DuplicateKeyException ignored) {
309	            // 锁行已存在，直接进入下行加锁
310	        }
311	        jdbc.queryForObject("SELECT topic FROM bag_topic_lock WHERE topic = :topic FOR UPDATE",
312	                new MapSqlParameterSource("topic", topic), String.class);
313	    }
314	
315	    private void verifySameParams(MessageRow existing, WriteMessageRequest request, String payloadChecksum) {
316	        if (existing.timestampNs() != request.timestampNs()
317	                || !Objects.equals(existing.typeId(), request.typeId())
318	                || !Objects.equals(existing.payloadChecksum(), payloadChecksum)) {
319	            throw new ConflictException("批次号 " + request.batchNo()
320	                    + " 已存在但消息参数（时间戳/类型/负载）不一致，拒绝重试写入");
321	        }
322	    }
323	
324	    private void validateRange(Long startNs, Long endNs, Long startSeq, Long endSeq) {
325	        if (startNs != null && endNs != null && startNs > endNs) {
326	            throw new IllegalArgumentException("时间范围非法：startNs 不能大于 endNs");
327	        }
328	        if (startSeq != null && endSeq != null && startSeq > endSeq) {
329	            throw new IllegalArgumentException("序列号范围非法：startSeq 不能大于 endSeq");
330	        }
331	    }
332	
333	    private static byte[] decodePayload(String payloadBase64) {
334	        if (payloadBase64 == null || payloadBase64.isEmpty()) {
335	            return new byte[0];
336	        }
337	        try {
338	            return Base64.getDecoder().decode(payloadBase64);
339	        } catch (IllegalArgumentException e) {
340	            throw new IllegalArgumentException("payloadBase64 不是合法的 Base64 内容", e);
341	        }
342	    }
343	
344	    private static MessageView toView(MessageRow row) {
345	        return new MessageView(row.id(), row.topic(), row.timestampNs(), row.seq(), row.typeId(),
346	                Base64.getEncoder().encodeToString(row.payload() == null ? new byte[0] : row.payload()),
347	                row.payloadChecksum(), row.batchNo(), row.segmentId());
348	    }
349	
350	    private static long requireId(MessageRow row) {
351	        if (row == null) {
352	            throw new IllegalStateException("消息写入后回查失败");
353	        }
354	        return row.id();
355	    }
356	
357	    private static PlayRow requirePlay(PlayRow row) {
358	        if (row == null) {
359	            throw new IllegalStateException("回放记录写入后回查失败");
360	        }
361	        return row;
362	    }
363	}
