/** 按给定 id 列表回表并严格保持列表顺序（回放快照复现用）。 */
public List<MessageRow> findByIdsInOrder(List<Long> ids) {
    if (ids.isEmpty()) {
        return List.of();
    }
    List<MessageRow> rows = jdbc.query("SELECT * FROM bag_message WHERE id IN (:ids)",
            new MapSqlParameterSource("ids", ids), MAPPER);
    java.util.Map<Long, MessageRow> byId = new java.util.HashMap<>();
    for (MessageRow row : rows) {
        byId.put(row.id(), row);
    }
    List<MessageRow> ordered = new java.util.ArrayList<>(ids.size());
    for (Long id : ids) {
        MessageRow row = byId.get(id);
        if (row != null) {
            ordered.add(row);
        }
    }
    return ordered;
}

